// components/FeedbackForm.js
'use client';
import { useState } from 'react';

export default function FeedbackForm({ onSubmit }) {
  const [message, setMessage] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (onSubmit) onSubmit(message);
    setSubmitted(true);
  };

  if (submitted) {
    return <p className="success">Thank you!</p>;
  }

  return (
    <form onSubmit={handleSubmit}>
      <textarea placeholder="Your feedback" value={message} onChange={(e) => setMessage(e.target.value)} />
      <button type="submit">Send</button>
    </form>
  );
}

// __tests__/FeedbackForm.test.js
import { render, screen, fireEvent } from '@testing-library/react';
import FeedbackForm from '../components/FeedbackForm';

describe('FeedbackForm', () => {
  it('submits and shows success message', () => {
    const mockSubmit = jest.fn();
    render(<FeedbackForm onSubmit={mockSubmit} />);

    const textarea = screen.getByPlaceholderText('Your feedback');
    fireEvent.change(textarea, { target: { value: 'Nice work!' } });

    const button = screen.getByText('Send');
    fireEvent.click(button);

    expect(mockSubmit).toHaveBeenCalledWith('Nice work!');
    expect(screen.getByText('Thank you!')).toBeInTheDocument();
  });
});

// tests/feedback.spec.js (Playwright)
import { test, expect } from '@playwright/test';

test('submit feedback form', async ({ page }) => {
  await page.goto('/feedback');
  await page.fill('textarea[placeholder="Your feedback"]', 'Great app!');
  await page.click('button[type="submit"]');
  await expect(page.locator('.success')).toHaveText('Thank you!');
});

